1	package api
2	
3	import (
4		"errors"
5		"net/http"
6		"time"
7	
8		"example.com/tally/internal/auth"
9		"example.com/tally/internal/store"
10		"example.com/tally/internal/subscriptions"
11	)
12	
13	func subKey(s store.Subscription) cursor { return cursor{T: s.CreatedAt, ID: s.ID} }
14	
15	func (s *Server) subError(w http.ResponseWriter, err error) {
16		switch {
17		case errors.Is(err, subscriptions.ErrPlanInactive):
18			writeError(w, http.StatusUnprocessableEntity, "plan_inactive", err.Error())
19		case errors.Is(err, subscriptions.ErrCanceled):
20			writeError(w, http.StatusConflict, "subscription_canceled", err.Error())
21		default:
22			s.payError(w, err)
23		}
24	}
25	
26	func (s *Server) listSubscriptions(w http.ResponseWriter, r *http.Request, p auth.Principal) {
27		pg, ok := parsePage(w, r)
28		if !ok {
29			return
30		}
31		q := r.URL.Query()
32		subs := s.store.Subscriptions(p.OrgID, store.SubscriptionFilter{CustomerID: q.Get("customer_id"), Status: store.SubStatus(q.Get("status"))})
33		items, next := pageOf(subs, subKey, pg)
34		writeJSON(w, http.StatusOK, list{Items: items, NextCursor: next})
35	}
36	
37	func (s *Server) createSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
38		var in struct {
39			CustomerID      string `json:"customer_id"`
40			PlanID          string `json:"plan_id"`
41			Quantity        int    `json:"quantity"`
42			DiscountPercent int    `json:"discount_percent"`
43		}
44		if !decode(w, r, &in) {
45			return
46		}
47		sub, err := s.subs.Create(r.Context(), p.OrgID, subscriptions.CreateInput{CustomerID: in.CustomerID, PlanID: in.PlanID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent})
48		if err != nil && sub.ID == "" {
49			s.subError(w, err)
50			return
51		}
52		if err != nil {
53			s.log.Error("first invoice", "subscription", sub.ID, "err", err)
54		}
55		writeJSON(w, http.StatusCreated, sub)
56	}
57	
58	func (s *Server) getSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
59		sub, ok := s.store.Subscription(p.OrgID, r.PathValue("id"))
60		if !ok {
61			writeError(w, http.StatusNotFound, "not_found", "no such subscription")
62			return
63		}
64		writeJSON(w, http.StatusOK, sub)
65	}
66	
67	func (s *Server) updateSubscription(w http.ResponseWriter, r *http.Request, p auth.Principal) {
68		var in struct {
69			PlanID   *string `json:"plan_id"`
70			Quantity *int    `json:"quantity"`
71		}
