12	// CreatePlan adds a plan. UsageType defaults to Licensed; a new plan is active.
13	func (s *Store) CreatePlan(p Plan, now time.Time) (Plan, error) {
14		p.Name = strings.TrimSpace(p.Name)
15		if p.UsageType == "" {
16			p.UsageType = Licensed
17		}
18		p.Active = true
19		if err := checkPlan(p); err != nil {
20			return Plan{}, err
21		}
22		s.mu.Lock()
23		defer s.mu.Unlock()
24		if _, ok := s.orgs[p.OrgID]; !ok {
25			return Plan{}, ErrNotFound
26		}
27		p.ID = s.newID("plan")
28		p.CreatedAt = now.UTC()
29		s.plans[p.ID] = p
30		return p, nil
31	}
