33	func checkPlan(p Plan) error {
34		switch {
35		case p.Name == "":
36			return invalid("a plan needs a name")
37		case !p.Currency.Valid():
38			return invalid("unknown currency %q", p.Currency)
39		case p.UnitAmount < 0:
40			return invalid("a plan's price cannot be negative")
41		case p.Interval != Monthly && p.Interval != Yearly:
42			return invalid("a plan bills every month or every year")
43		case p.UsageType != Licensed && p.UsageType != Metered:
44			return invalid("a plan is licensed or metered")
45		case p.TrialDays < 0 || p.TrialDays > 365:
46			return invalid("a trial lasts 0 to 365 days")
47		}
48		return nil
49	}
