args.new_string:
// Update changes a subscription's plan or quantity. A subscription's value is its plan's unit amount times its quantity.
// A change that raises the value applies at once and is billed at once for the rest of the current period: the unused time
// on the old plan is credited and the remaining time on the new plan is charged. A change that lowers the value is pending
// until the next renewal. A change that keeps the value equal, and any change to a trialing subscription, applies at once
// and bills nothing.
func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
	if in.PlanID != nil {
		p, ok := s.Store.Plan(orgID, *in.PlanID)
		if !ok {
			return store.Subscription{}, store.ErrNotFound
		}
		if !p.Active {
			return store.Subscription{}, ErrPlanInactive
		}
	}
	cur, ok := s.Store.Subscription(orgID, id)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if cur.Status == store.Canceled {
		return store.Subscription{}, ErrCanceled
	}
	planID, qty := cur.PlanID, cur.Quantity
	if in.PlanID != nil {
		planID = *in.PlanID
	}
	if in.Quantity != nil {
		qty = *in.Quantity
	}
	if qty <= 0 {
		return store.Subscription{}, fmt.Errorf("%w: the quantity must be at least 1", store.ErrInvalid)
	}
	if planID == cur.PlanID && qty == cur.Quantity {
		// Back to the current plan and quantity: nothing changes, and a pending change is withdrawn.
		return s.change(ctx, orgID, id, func(x *store.Subscription) { x.PendingPlanID, x.PendingQuantity = nil, nil })
	}
	oldPlan, ok := s.Store.Plan(orgID, cur.PlanID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	newPlan, ok := s.Store.Plan(orgID, planID)
	if !ok {
		return store.Subscription{}, store.ErrNotFound
	}
	if oldPlan.UsageType == store.Metered || newPlan.UsageType == store.Metered || oldPlan.Currency != newPlan.Currency || oldPlan.Interval != newPlan.Interval {
		return store.Subscription{}, ErrIncompatiblePlan
	}
	oldValue, newValue := oldPlan.UnitAmount*int64(cur.Quantity), newPlan.UnitAmount*int64(qty)
	switch {
	case cur.Status == store.Trialing, newValue == oldValue:
		return s.change(ctx, orgID, id, func(x *store.Subscription) {
			x.PlanID, x.Quantity, x.PendingPlanID, x.PendingQuantity = planID, qty, nil, nil
		})
	case newValue < oldValue:
		return s.change(ctx, orgID, id, func(x *store.Subscription) {
			x.PendingPlanID, x.PendingQuantity = &planID, &qty
		})
	default:
		return s.upgrade(ctx, cur, oldPlan, newPlan, qty)
	}
}

// upgrade applies a change that raises a subscription's value and bills it at once: an invoice credits the unused time on the
// old plan and charges the remaining time on the new one. A declined charge makes the subscription past due. The current
// period does not change.
func (s *Service) upgrade(ctx context.Context, cur store.Subscription, oldPlan, newPlan store.Plan, qty int) (store.Subscription, error) {
	now := s.Clock.Now()
	remaining, length := remainingAndLength(cur, now)
	end := cur.CurrentPeriodEnd
	inv, err := s.Store.CreateInvoice(store.Invoice{OrgID: cur.OrgID, CustomerID: cur.CustomerID, SubscriptionID: cur.ID, Currency: newPlan.Currency,
		Lines: []store.Line{
			{Description: "Unused time on " + oldPlan.Name, Quantity: 1, UnitAmount: -money.Prorate(oldPlan.UnitAmount*int64(cur.Quantity), remaining, length)},
			{Description: "Remaining time on " + newPlan.Name, Quantity: 1, UnitAmount: money.Prorate(newPlan.UnitAmount*int64(qty), remaining, length)},
		},
		DiscountPercent: cur.DiscountPercent, PeriodStart: &now, PeriodEnd: &end}, now)
	if err != nil {
		return store.Subscription{}, err
	}
	sub, err := s.change(ctx, cur.OrgID, cur.ID, func(x *store.Subscription) {
		x.PlanID, x.Quantity, x.PendingPlanID, x.PendingQuantity = newPlan.ID, qty, nil, nil
	})
	if err != nil {
		return sub, err
	}
	s.publish(ctx, cur.OrgID, "invoice.created", map[string]any{"invoice_id": inv.ID, "subscription_id": cur.ID})
	paid, err := s.charge(ctx, cur.OrgID, inv.ID)
	if err != nil {
		return sub, err
	}
	if !paid {
		return s.setStatus(ctx, sub, store.PastDue)
	}
	return sub, nil
}

// change applies f to a subscription, which must not be canceled, and publishes the update.
func (s *Service) change(ctx context.Context, orgID, id string, f func(*store.Subscription)) (store.Subscription, error) {
	sub, err := s.Store.UpdateSubscription(orgID, id, func(x *store.Subscription) error {
		if x.Status == store.Canceled {
			return ErrCanceled
		}
		f(x)
		return nil
	})
	if err != nil {
		return store.Subscription{}, err
	}
	s.publish(ctx, orgID, "subscription.updated", sub)
	return sub, nil
}

// remainingAndLength returns the seconds from now to the end of sub's current period, kept within the period, and the
// period's length in seconds.
func remainingAndLength(sub store.Subscription, now time.Time) (remaining, length int64) {
	length = int64(sub.CurrentPeriodEnd.Sub(sub.CurrentPeriodStart) / time.Second)
	remaining = int64(sub.CurrentPeriodEnd.Sub(now) / time.Second)
	return min(max(remaining, 0), length), length
}

