func TestUpgradeBillsTheRemainingTime(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	e.Clock.Advance(10 * 24 * time.Hour) // 21 of the period's 31 days remain

	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID})
	if err != nil || got.PlanID != pro.ID || got.Status != store.Active || got.PendingPlanID != nil || got.PendingQuantity != nil {
		t.Fatalf("upgrade = %+v, %v", got, err)
	}
	if !got.CurrentPeriodStart.Equal(sub.CurrentPeriodStart) || !got.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("the upgrade moved the period: %+v", got)
	}
	inv, ok := prorationInvoice(e, sub.ID)
	// Unused: 2000 * 21/31 = 1354.84 -> 1355. Remaining: 5000 * 21/31 = 3387.10 -> 3387.
	want := []store.Line{{Description: "Unused time on Team", Quantity: 1, UnitAmount: -1355}, {Description: "Remaining time on Pro", Quantity: 1, UnitAmount: 3387}}
	if !ok || inv.Status != store.InvoicePaid || !slices.Equal(inv.Lines, want) {
		t.Fatalf("proration invoice = %+v, %v", inv, ok)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 || cs[1].Amount != 2032 {
		t.Fatalf("charges = %+v", cs)
	}
}

