func TestDowngradeTakesEffectAtRenewal(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = "pm_card_visa"; return nil })
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	pro := e.CreatePlan(e.Acme, "Pro", "USD", "50.00")
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: pro.ID, Quantity: 2})
	if err != nil {
		t.Fatal(err)
	}
	one, two := 1, 2
	got, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &team.ID, Quantity: &one})
	if err != nil || got.PlanID != pro.ID || got.Quantity != 2 || got.PendingPlanID == nil || *got.PendingPlanID != team.ID || got.PendingQuantity == nil || *got.PendingQuantity != 1 {
		t.Fatalf("downgrade = %+v, %v", got, err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 1 {
		t.Fatalf("a downgrade was billed: %+v", invs)
	}

	// Back to the current plan and quantity withdraws the pending change.
	got, err = e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &pro.ID, Quantity: &two})
	if err != nil || got.PendingPlanID != nil || got.PendingQuantity != nil {
		t.Fatalf("back to the current plan = %+v, %v", got, err)
	}

	if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &team.ID, Quantity: &one}); err != nil {
		t.Fatal(err)
	}
	e.Clock.Set(sub.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(ctx); err != nil || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ = e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.PlanID != team.ID || got.Quantity != 1 || got.PendingPlanID != nil || got.PendingQuantity != nil || got.Status != store.Active {
		t.Fatalf("after the renewal = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || len(invs[1].Lines) != 1 || invs[1].Lines[0].UnitAmount != 2000 || invs[1].Lines[0].Quantity != 1 {
		t.Fatalf("renewal invoice = %+v", invs)
	}
}

