func TestIncompatiblePlansAreRefused(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	team := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	euro := e.CreatePlan(e.Acme, "Euro", "EUR", "20.00")
	yearly, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Yearly", Currency: money.USD, UnitAmount: 20000, Interval: store.Yearly}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	metered, err := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "Calls", Currency: money.USD, UnitAmount: 2, Interval: store.Monthly, UsageType: store.Metered}, e.Clock.Now())
	if err != nil {
		t.Fatal(err)
	}
	sub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: team.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	for _, target := range []string{euro.ID, yearly.ID, metered.ID} {
		if _, err := e.Subs.Update(ctx, e.Acme.ID, sub.ID, subscriptions.UpdateInput{PlanID: &target}); !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
			t.Fatalf("change to %s: %v", target, err)
		}
	}
	meteredSub, err := e.Subs.Create(ctx, e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: metered.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := e.Subs.Update(ctx, e.Acme.ID, meteredSub.ID, subscriptions.UpdateInput{PlanID: &team.ID}); !errors.Is(err, subscriptions.ErrIncompatiblePlan) {
		t.Fatalf("change a metered subscription: %v", err)
	}
	if got, _ := e.Store.Subscription(e.Acme.ID, sub.ID); got.PlanID != team.ID {
		t.Fatalf("a refused change applied: %+v", got)
	}
}

